def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/archeology/input/roman_cities.csv'
    return pd.read_csv(path)

def process(romanCities):
    import pandas as pd
    import numpy as np

    df = romanCities.copy()

    # Filter to Greece
    df = df[df["Country"].astype(str).str.strip().str.lower() == "greece"].copy()

    # Parse Barrington Atlas Rank where values can be like '4 or 5', '-', '3', etc.
    s = df["Barrington Atlas Rank"].astype(str).str.strip().str.lower()

    def parse_rank(x: str):
        if x in {"-", "", "nan", "none"}:
            return np.nan
        if "or" in x:
            parts = [p.strip() for p in x.split("or")]
            nums = []
            for p in parts:
                try:
                    nums.append(float(p))
                except Exception:
                    pass
            return float(np.mean(nums)) if nums else np.nan
        try:
            return float(x)
        except Exception:
            return np.nan

    df["rankNumeric"] = s.map(parse_rank)

    avg_rank = df["rankNumeric"].mean()

    return pd.DataFrame([{"avg_rank": avg_rank}])
